@users_bp.route("/filter", methods=["GET"])
@require_role("manager")
def filter_users():
    clauses = []
    for field, value in request.args.items():
        clauses.append(f"{field} = '{value}'")
    where = " AND ".join(clauses) or "1=1"
    session = get_session()
    rows = session.execute(
        text("SELECT id, username, role FROM users WHERE " + where)
    )
    return jsonify([dict(r._mapping) for r in rows])

def require_role(minimum_role: str):
    """Require at least the given role (user < manager < admin)."""
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            user = get_current_user()
            if user is None:
                return jsonify({"error": "authentication required"}), 401
            if ROLE_RANK.get(user.role, 0) < ROLE_RANK.get(minimum_role, 99):
                return jsonify({"error": "insufficient role"}), 403
            g.current_user = user
            return fn(*args, **kwargs)
        return wrapper
    return decorator

findings.suggested_fix:
Do not interpolate request values into the SQL string. (1) Validate each `field` against a hard-coded allowlist of permitted columns (e.g. {"id", "username", "role"}) and reject anything else. (2) Use bound parameters for the values: build `text("SELECT id, username, role FROM users WHERE " + where)` where `where` is composed of `:p0 AND :p1 ...` placeholders, and pass a params dict to `session.execute(stmt, params)`. Example:

ALLOWED_FIELDS = {"id", "username", "role"}
clauses, params = [], {}
for i, (field, value) in enumerate(request.args.items()):
    if field not in ALLOWED_FIELDS:
        return jsonify({"error": "invalid field"}), 400
    key = f"p{i}"
    clauses.append(f"{field} = :{key}")
    params[key] = value
where = " AND ".join(clauses) or "1=1"
stmt = text(f"SELECT id, username, role FROM users WHERE {where}")
rows = session.execute(stmt, params)

This keeps column names whitelisted (safe to interpolate) and binds all user-supplied values as parameters, satisfying security-policy.md §5.

